package io.tornado.persistence;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="best_method_mixes",uniqueConstraints=@UniqueConstraint(name="uk_best_mix_slice_rank_version_tp",columnNames={"coin_id","horizon_seconds","mix_size","rank_number","signal_version","tp_level"}))
public class BestMethodMix{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="coin_id")private Coin coin;private long horizonSeconds;private int mixSize;@Column(name="rank_number")private int rank;@Column(length=1000)private String strategyCodes;@Column(length=500)private String strategyVersions;@Column(length=2000)private String methodNames;private long samples;private long targetHits;private double targetHitRate;private long directionalCorrect;private double directionalAccuracy;private double wilsonScore;private double rankingScore;private int signalVersion;private int tpLevel=1;@Column(precision=8,scale=4)private java.math.BigDecimal targetPercent=new java.math.BigDecimal("0.30");private Instant calculatedAt;
 protected BestMethodMix(){}public BestMethodMix(Coin coin,long horizon,int size,int rank,List<String>codes,List<Integer>versions,List<String>names,long samples,long hits,long directional,double wilson){this(coin,horizon,size,rank,codes,versions,names,samples,hits,directional,wilson,1,new java.math.BigDecimal("0.30"));}public BestMethodMix(Coin coin,long horizon,int size,int rank,List<String>codes,List<Integer>versions,List<String>names,long samples,long hits,long directional,double wilson,int tpLevel,java.math.BigDecimal targetPercent){this.coin=coin;horizonSeconds=horizon;mixSize=size;this.rank=rank;strategyCodes=String.join("||",codes);strategyVersions=versions.stream().map(String::valueOf).collect(java.util.stream.Collectors.joining("||"));methodNames=String.join("||",names);this.samples=samples;targetHits=hits;targetHitRate=samples==0?0:hits*100.0/samples;directionalCorrect=directional;directionalAccuracy=samples==0?0:directional*100.0/samples;wilsonScore=wilson*100;rankingScore=wilsonScore;signalVersion=3;this.tpLevel=tpLevel;this.targetPercent=targetPercent;calculatedAt=Instant.now();}
 public Long getId(){return id;}public Coin getCoin(){return coin;}public long getHorizonSeconds(){return horizonSeconds;}public int getMixSize(){return mixSize;}public int getRank(){return rank;}public List<String>getStrategyCodes(){return split(strategyCodes);}public List<Integer>getStrategyVersions(){return split(strategyVersions).stream().map(Integer::valueOf).toList();}public List<String>getMethodNames(){return split(methodNames);}public long getSamples(){return samples;}public long getTargetHits(){return targetHits;}public double getTargetHitRate(){return targetHitRate;}public long getDirectionalCorrect(){return directionalCorrect;}public double getDirectionalAccuracy(){return directionalAccuracy;}public double getWilsonScore(){return wilsonScore;}public double getRankingScore(){return rankingScore;}public int getSignalVersion(){return signalVersion;}public int getTpLevel(){return tpLevel;}public java.math.BigDecimal getTargetPercent(){return targetPercent;}public Instant getCalculatedAt(){return calculatedAt;}private List<String>split(String s){return s==null||s.isEmpty()?List.of():Arrays.asList(s.split("\\|\\|",-1));}
}
